#!/usr/bin/env python3
# Write an SVG comparing cell and homology Euler sums.
from pathlib import Path

def render(cells: tuple[int,int,int]=(3,3,1), betti: tuple[int,int,int]=(1,0,0)) -> None:
    chi_c=cells[0]-cells[1]+cells[2]; chi_h=betti[0]-betti[1]+betti[2]
    if chi_c != chi_h: raise ValueError("Euler identity fails")
    bars=[]
    for group,vals,x0,color in [("Cells",cells,90,"#4361ee"),("Homology",betti,430,"#7209b7")]:
        bars.append(f'<text x="{x0+100}" y="55" text-anchor="middle" font-size="20">{group}</text>')
        for i,v in enumerate(vals):
            h=35*v; x=x0+i*75
            bars.append(f'<rect x="{x}" y="{220-h}" width="48" height="{h}" fill="{color}"/><text x="{x+24}" y="245" text-anchor="middle">{group[0].lower()}{i}={v}</text>')
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="720" height="300"><rect width="100%" height="100%" fill="#fffaf0"/>{''.join(bars)}<text x="360" y="282" text-anchor="middle">Both alternating sums equal χ = {chi_c}</text></svg>'''
    Path("euler_profile.svg").write_text(svg)
render()
